<?php require 'config.php';require_role('restaurant');$uid=current_user()['id'];$s=$pdo->prepare("SELECT * FROM restaurants WHERE user_id=?");$s->execute([$uid]);$r=$s->fetch();if(!$r)exit('Restaurant profile missing.');verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add_food'])){$name=trim($_POST['name']??'');$price=(float)($_POST['price']??0);if(!$name||$price<=0)$error='Enter a food name and a valid price.';elseif(!$r['approved'])$error='Your restaurant must be approved before adding menu items.';else{$s=$pdo->prepare("INSERT INTO foods(restaurant_id,name,description,price) VALUES(?,?,?,?)");$s->execute([$r['id'],$name,trim($_POST['description']??''),$price]);flash('Food item added.');redirect('restaurant.php');}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['toggle'])){$s=$pdo->prepare("UPDATE foods SET available=1-available WHERE id=? AND restaurant_id=?");$s->execute([(int)$_POST['toggle'],$r['id']]);redirect('restaurant.php');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['status_order'])){$allowed=['Accepted','Preparing','On the way','Delivered','Cancelled'];$status=$_POST['status']??'';if(in_array($status,$allowed,true)){$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=? AND restaurant_id=?");$s->execute([$status,(int)$_POST['status_order'],$r['id']]);flash('Order status updated.');}redirect('restaurant.php');}
$s=$pdo->prepare("SELECT * FROM foods WHERE restaurant_id=? ORDER BY id DESC");$s->execute([$r['id']]);$foods=$s->fetchAll();$s=$pdo->prepare("SELECT * FROM orders WHERE restaurant_id=? ORDER BY id DESC");$s->execute([$r['id']]);$orders=$s->fetchAll();$pageTitle='Restaurant dashboard';include 'partials/header.php';?>
<h1>Restaurant dashboard</h1><div class="alert <?=$r['approved']?'success':'warning'?>"><?= $r['approved']?'Your restaurant is approved and visible to customers.':'Your restaurant is waiting for admin approval.' ?></div><h2><?=e($r['name'])?></h2><p class="muted"><?=e($r['area'])?> · <?=e($r['address'])?></p>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="form-card" style="margin:20px 0"><h2>Add food item</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="add_food" value="1"><label>Food name</label><input name="name" required><label>Description</label><textarea name="description"></textarea><label>Price (৳)</label><input type="number" name="price" min="1" step=".01" required><div class="spacer"></div><button class="btn">Add food</button></form></div>
<h2>Menu items</h2><div class="table-wrap"><table><tr><th>Food</th><th>Price</th><th>Availability</th><th>Action</th></tr><?php foreach($foods as $f):?><tr><td><?=e($f['name'])?></td><td>৳<?=number_format((float)$f['price'],2)?></td><td><?=$f['available']?'Available':'Unavailable'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn-secondary" name="toggle" value="<?=$f['id']?>">Toggle</button></form></td></tr><?php endforeach;?></table></div>
<h2>Incoming orders</h2><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Address / Phone</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['delivery_address'])?><br><?=e($o['phone'])?></td><td>৳<?=number_format((float)$o['total'],2)?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="status_order" value="<?=$o['id']?>"><select name="status"><?php foreach(['Accepted','Preparing','On the way','Delivered','Cancelled'] as $st):?><option <?=$st===$o['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn-secondary">Save</button></form></td></tr><?php endforeach;?></table></div>
<?php include 'partials/footer.php';?>
